// ai-agents/orchestrator/src/workflows/ticket-to-pr.ts: the messages a run accepts
import { defineQuery, defineSignal, setHandler } from "@temporalio/workflow";
import type { Handoff, PlanDecision, RunState } from "@rhinohealth/ai-agents-shared";

export const decidePlan = defineSignal<[PlanDecision]>("decidePlan"); // Slack buttons, @Nova approve
export const answerQuestion = defineSignal<[text: string, by: string]>("answerQuestion"); // a reply in the thread
export const stop = defineSignal<[by: string]>("stop"); // Stop button, /nova stop, unassign
export const status = defineQuery<string>("status"); // /nova status RH-1234

export async function ticketToPr(t: Handoff): Promise<string> {
  const run: RunState = { stopped: false };
  let decision: PlanDecision | undefined;
  let state = "Checking";
  setHandler(decidePlan, (d) => { decision ??= d; }); // the first decision wins (G3-35)
  setHandler(answerQuestion, (text) => { run.answer = run.answer ? `${run.answer}\n${text}` : text; });
  setHandler(stop, () => { run.stopped = true; });
  setHandler(status, () => state); // a query only reads
  // ... plan, wait, build: the rest of G3-24
}

// ai-agents/orchestrator/src/waiting.ts: workflow code. Waiting costs nothing in Temporal.
import { condition } from "@temporalio/workflow";
import { act } from "./policies.js";

const DAY = 24 * 60 * 60 * 1000;
const WAITS: Record<Wait, [remindAfterMs: number, parkAfterMs: number]> = {
  plan: [1 * DAY, 3 * DAY],
  question: [1 * DAY, 2 * DAY],
  review: [2 * DAY, 14 * DAY],
};

/** True when the person acted; false when the ticket was parked. Stop always wins. */
export const waitForPerson = async (wf: RunState, what: Wait, done: () => boolean, t: Handoff): Promise<boolean> => {
  const [remind, park] = scaled(WAITS[what], t.drill); // minutes instead of days on drill tickets
  if (await condition(() => done() || wf.stopped, remind)) return !wf.stopped;
  await act.notify(t, REMINDERS[what](t.requester)); // Slack thread, Jira if Slack is down
  if (await condition(() => done() || wf.stopped, park - remind)) return !wf.stopped;
  await act.parkTicket(t, PARK_NOTES[what]); // G4 decides the Jira status and assignee
  return false;
};

// inside inSandbox (G3-24): the agent stopped because it needs an answer
run.answer = undefined; // cleared before the run, so a quick reply to its question is never lost
let result = await act.workInSandbox(vm, task);
while (result.needsAnswer) {
  const idle = !(await condition(() => run.answer !== undefined, "10 minutes")); // no answer yet
  if (idle) await act.parkSandbox(vm); // stop the VM and keep its disk while a person thinks
  if (!(await waitForPerson(run, "question", () => run.answer !== undefined, t))) return { ...result, parked: true };
  if (idle) await act.wakeSandbox(vm); // start it again, freshen if main moved
  const reply = run.answer ?? ""; run.answer = undefined;
  result = await act.workInSandbox(vm, resumeTask(task, result.sessionId, reply));
}

// a client, for example the Slack app (G3-35): signals and queries by workflow ID
const handle = client.workflow.getHandle("nova:RH-1234"); // no run ID needed
await handle.signal(decidePlan, { kind: "approve", by: "dana@example.com", version: "v2" });
await handle.signal(answerQuestion, "Use the empty-state card", "dana@example.com");
const now = await handle.query(status); // a worker answers from the run's current state
console.log(now); // "Awaiting approval"

