import { condition, defineQuery, defineSignal, proxyActivities, setHandler } from "@temporalio/workflow";
import type * as activities from "./activities.js";

const { greet } = proxyActivities<typeof activities>({ startToCloseTimeout: "1 minute" });
export const approve = defineSignal<[by: string]>("approve");
export const status = defineQuery<string>("status");

export async function hello(name: string): Promise<string> {
  let state = "waiting";
  let approvedBy: string | undefined;
  setHandler(approve, (by) => { approvedBy = by; });
  setHandler(status, () => state);
  const inTime = await condition(() => approvedBy !== undefined, "1 day"); // false after a day
  if (!inTime) { state = "parked"; return "parked"; }
  state = "working";
  return `${await greet(name)} (approved by ${approvedBy})`;
}
